tags: [pooling, stringbuilder, object-pool, allocations]
code:
  language: csharp
  harness: statements
  source: |
    using System.Text;

    Stack<StringBuilder> pool = new();

    StringBuilder Rent()
    {
        return pool.Count > 0 ? pool.Pop() : new StringBuilder();
    }

    void Return(StringBuilder builder)
    {
        pool.Push(builder);
    }

    string FormatMessage(string user, int unread)
    {
        StringBuilder builder = Rent();
        try
        {
            builder.Append(user).Append(": ").Append(unread).Append(" unread");
            return builder.ToString();
        }
        finally
        {
            Return(builder);
        }
    }

    Console.WriteLine(FormatMessage("alice", 3));
    Console.WriteLine(FormatMessage("bob", 5));
bugLineSets: [[12]]
fixedSource: |
  using System.Text;

  Stack<StringBuilder> pool = new();

  StringBuilder Rent()
  {
      return pool.Count > 0 ? pool.Pop() : new StringBuilder();
  }

  void Return(StringBuilder builder)
  {
      builder.Clear();
      pool.Push(builder);
  }

  string FormatMessage(string user, int unread)
  {
      StringBuilder builder = Rent();
      try
      {
          builder.Append(user).Append(": ").Append(unread).Append(" unread");
          return builder.ToString();
      }
      finally
      {
          Return(builder);
      }
  }

  Console.WriteLine(FormatMessage("alice", 3));
  Console.WriteLine(FormatMessage("bob", 5));
fixedExpect: { kind: output, value: "alice: 3 unread\nbob: 5 unread" }
